#!/usr/bin/env bash
# Builds the Claude Code plugin files from prompt/ and references/ (the single source of truth).
#   ./scripts/build.sh           # regenerate
#   ./scripts/build.sh --check   # CI: fail if generated files are out of date
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
P="$ROOT/prompt"; R="$ROOT/references"; PLUGIN="$ROOT/plugins/gdpreu"
HEADER="<!-- GENERATED by scripts/build.sh from prompt/ and references/ — do not edit by hand. -->"

# In a skill, "!" followed by a backtick runs a shell command. Never let prompt text trigger that by accident.
if grep -n '!`' "$P"/*.md "$R"/*.md; then
  echo "error: prompt text contains '!\`', which Claude Code would execute as a shell command — rephrase it" >&2
  exit 1
fi

knowledge() {
  printf '\n---\n\n'
  cat "$R/checks.md"
  printf '\n---\n\n'
  cat "$R/countries.md"
}

build_skill_check() {
  cat <<'FRONT'
---
name: check
description: Check GDPR EU Agent by openways.ai — audit a website (URL) and/or codebase for EU cookie & tracking consent problems (ePrivacy art. 5(3) + GDPR) across EU countries and the UK. Read-only evidence report; not legal advice.
argument-hint: "<url> | [path] | <url> <path>  [countries, e.g. CZ,DE]"
disable-model-invocation: true
disallowed-tools: Edit, Write, NotebookEdit
allowed-tools: Bash(node ${CLAUDE_PLUGIN_ROOT}/crawler/crawl.mjs *) Bash(node ${CLAUDE_PLUGIN_ROOT}/scripts/scan-code.mjs *)
---
FRONT
  echo "$HEADER"
  cat <<'TASK'

**Task:** Run the Check GDPR EU Agent described below.

**Arguments:** `$ARGUMENTS`
- A URL means `site` mode, a path (or nothing) means `code` mode, both mean `full` mode.
- Country codes (e.g. `CZ,DE`) set the target countries. Otherwise infer them and state your assumption.

Begin your first message with the responsibility notice (§0), then state the mode, targets and countries.

TASK
  cat "$P/gdpr-eu-agent.md" "$P/claude-code-addendum.md"
  knowledge
}

build_agent_auditor() {
  cat <<'FRONT'
---
name: gdpr-auditor
description: Check GDPR EU Agent by openways.ai. Audits websites and codebases for EU cookie and tracking consent problems (ePrivacy art. 5(3), GDPR consent, EDPB guidance, national rules for 16 jurisdictions) and returns an evidence-based report with a not-legal-advice notice. Read-only. Use when the user asks whether a site or app handles cookies, tracking or consent correctly under GDPR.
tools: Read, Grep, Glob, Bash, WebFetch
disallowedTools: Edit, Write, NotebookEdit
model: inherit
color: blue
---
FRONT
  echo "$HEADER"
  echo
  cat "$P/gdpr-eu-agent.md" "$P/claude-code-addendum.md"
  cat <<'LOCATE'

If `${CLAUDE_PLUGIN_ROOT}` is not expanded in the commands above, find the plugin folder first, e.g. `ls -d ~/.claude/plugins/cache/*/gdpreu/*/ 2>/dev/null | tail -1`.
LOCATE
  knowledge
}

TARGETS=("skill_check:skills/check/SKILL.md" "agent_auditor:agents/gdpr-auditor.md")
check=0
[[ "${1:-}" == "--check" ]] && check=1
status=0
for t in "${TARGETS[@]}"; do
  fn="build_${t%%:*}"; out="$PLUGIN/${t#*:}"
  if (( check )); then
    diff -q <("$fn") "$out" >/dev/null 2>&1 || { echo "out of date: ${out#"$ROOT"/} (run ./scripts/build.sh)"; status=1; }
  else
    mkdir -p "$(dirname "$out")"; "$fn" > "$out"; echo "built ${out#"$ROOT"/}"
  fi
done
exit $status
